test('source expected494 plus exact22 yields516 complete tagged fingerprint records and fixed basis',()=>{
 assert.equal(basis.records.length,516);assert.equal(new Set(basis.records.map(id)).size,516);assert.equal(basis.after.length,22);assert.equal(basis.external_records.length,36);
 assert.deepEqual(basis.basis,{count:1,bytes:3590688,sha:'db01b0c7849fc9771ab7d6a7cf41ff79d8e5c4eec1a96ee0c0637f17902f12b3'});
 const functions=basis.records.filter(r=>r.kind==='function');assert.equal(functions.length,49);
 for(const r of functions){const raw=expectedAdditions.find(a=>id(a)===id(r))?.value||expectedChanges.find(c=>id(c)===id(r))?.after;assert(raw);
  assert.deepEqual(r.value.source,['sha256-utf8-text/v1',sha(raw.source)]);assert.deepEqual(r.value.definition,['sha256-utf8-text/v1',sha(raw.definition)]);
  assert.equal(r.value.owner,raw.owner);assert.deepEqual(r.value.acl,raw.acl);assert.deepEqual(Object.keys(r.value).sort(),Object.keys(raw).sort());}
 assert.equal(basis.fingerprint_input_sha256,digest({records:basis.records,basis:basis.basis}));
 assert.deepEqual(basis.records.map(id),[...basis.records.map(id)].sort());assert(Object.isFrozen(basis)&&Object.isFrozen(basis.records[0].value));
});

