test('seal guards actual complete source,22 AFTER,36external,sourcebasis and exact parent originals before single INSERT',()=>{
 const sql=unquoted(body(script.sql)),insert=sql.indexOf('INSERT INTO public.order_split210_manifest');assert(insert>0);
 for(const guard of ['jsonb_array_length(actual_own)<>494','actual_after IS DISTINCT FROM expected_after','actual_records IS DISTINCT FROM expected_records',
  'actual_basis IS DISTINCT FROM expected_basis','actual_external IS DISTINCT FROM expected_external','actual_fingerprint IS DISTINCT FROM expected_fingerprint'])assert(sql.indexOf(guard)>=0&&sql.indexOf(guard)<insert,guard);
 assert(sql.includes('p209 IS DISTINCT FROM(SELECT to_jsonb(p) FROM public.order_merge_delivery209_manifest p)'));
 assert(sql.includes('p166 IS DISTINCT FROM(SELECT to_jsonb(p) FROM public.buyer_address_manifest p)'));
 assert(body(script.sql).includes("OR p209->'original166' IS DISTINCT FROM p166"));
 assert(sql.includes('(SELECT count(*) FROM public.order_split210_manifest)<>0'));
 assert(sql.includes('payload_octets=3590688'));assert(body(script.sql).includes("payload_sha256='db01b0c7849fc9771ab7d6a7cf41ff79d8e5c4eec1a96ee0c0637f17902f12b3'"));
 assert(body(script.sql).includes("payload_jsonb->>'schema'='order-split210-projection-basis/definition-codec-v1'"));
  assert(!body(script.sql).includes("payload_jsonb->>'schema'='order-split210-projection-basis/v1'"));
  assert.equal((sql.match(/INSERT INTO public\.order_split210_manifest/g)||[]).length,1);
 assert(!/\b(?:CREATE|ALTER|DROP|GRANT|REVOKE|TEMP|EXECUTE)\b/.test(sql));
 assert(sql.indexOf('public.order_split210_valid() IS DISTINCT FROM true')>insert,'actual sealed Native readback must raise on failure');
 assert.equal(script.parent_capture_verified,false);assert.equal(script.seal_executed,false);assert.equal(script.native_certification,false);assert.equal(script.application_activation,false);
});

